const { useReducer } = React;

function reducer(state, action) {
  if (action.type === 'set') return action.payload;
  if (action.type === 'add') return state + action.payload;
  return state;
}

function Quantity() {
  const [quantity, dispatch] = useReducer(reducer, 0);
  return (
    <section>
      <p>수량: {quantity}</p>
      <button type="button" onClick={() => dispatch({ type: 'set', payload: 5 })}>5로 설정</button>
      <button type="button" onClick={() => dispatch({ type: 'add', payload: 3 })}>3 추가</button>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Quantity />);

